def find_asset(name):
    """Resolve the same exported filenames used in the Colab workflow."""
    for folder in (BASE_DIR, BASE_DIR / "used_car_regression_outputs"):
        candidate = folder / name
        if candidate.is_file():
            return candidate
    return None


@st.cache_resource(show_spinner="Loading the saved price model…")
def load_model(path, modified_ns):
    # Timestamp in the cache key makes replacing the model invalidate the cache.
    model = joblib.load(path)
    if not isinstance(model, Pipeline) or "preprocessor" not in model.named_steps:
        raise ValueError("Expected the complete preprocessing-and-model Pipeline "
                         "exported by the used car Colab workflow.")
    expected = list(getattr(model, "feature_names_in_", []))
    if set(expected) != set(FEATURES):
        raise ValueError("The model's raw input columns do not match this dashboard. "
                         "Use used_car_price_model.pkl from the used car workflow.")
    return model


def read_optional_json(path):
    if path is None:
        return {}
    try:
        return json.loads(path.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        st.warning("Could not read model_metadata.json. Predictions are still available.")
        return {}


def get_categories(model):
    """Read categories from the fitted encoder, not from an invented mapping."""
    preprocessor = model.named_steps["preprocessor"]
    encoder = preprocessor.named_transformers_["categorical"].named_steps["encoder"]
    return {column: list(values) for column, values
            in zip(CATEGORICAL, encoder.categories_)}


def validate_inputs(frame, categories):
    """Check raw records; allow blanks for the saved pipeline's imputation."""
    if frame.empty:
        raise ValueError("No car records were provided.")
    absent = sorted(set(FEATURES) - set(frame.columns))
    if absent:
        raise ValueError("Missing columns: " + ", ".join(absent))
    clean = frame[FEATURES].copy()
    for column in NUMERIC:
        original = clean[column].replace(r"^\s*$", np.nan, regex=True)
        numeric = pd.to_numeric(original, errors="coerce")
        if (original.notna() & numeric.isna()).any():
            raise ValueError(f"{column} must contain numbers or blank cells.")
        if np.isinf(numeric.dropna().to_numpy(dtype=float)).any():
            raise ValueError(f"{column} contains an infinite value.")
        clean[column] = numeric.astype(float)
    for column in ["vehicle_age_years", "mileage_km", "previous_owners"]:
        if (clean[column].dropna() < 0).any():
            raise ValueError(f"{column} cannot be negative.")
    if (clean["engine_size_l"].dropna() <= 0).any():
        raise ValueError("engine_size_l must be greater than zero.")
    rating = clean["condition_rating"].dropna()
    if ((rating < 1) | (rating > 5) | (rating % 1 != 0)).any():
        raise ValueError("condition_rating must be a whole number from 1 to 5.")
    if (clean["previous_owners"].dropna() % 1 != 0).any():
        raise ValueError("previous_owners must be a whole number.")
    for column in CATEGORICAL:
        clean[column] = clean[column].map(
            lambda x: x.strip() if isinstance(x, str) else x
        ).replace("", np.nan)
        unknown = clean[column].notna() & ~clean[column].isin(categories[column])
        if unknown.any():
            raise ValueError(f"Unknown {column}. Use: {', '.join(categories[column])}.")
    return clean


def predict_prices(model, frame, categories):
    raw = validate_inputs(frame, categories)
    raw = raw[list(model.feature_names_in_)]
    predictions = np.asarray(model.predict(raw), dtype=float).reshape(-1)
    if len(predictions) != len(raw) or not np.isfinite(predictions).all():
        raise ValueError("The model returned invalid predictions.")
    return predictions


def csv_bytes(frame):
    return frame.to_csv(index=False).encode("utf-8-sig")


