model_path = find_asset("used_car_price_model.pkl")
if model_path is None:
    st.info("Add your trained model to start predicting.")
    st.markdown("Place **used_car_price_model.pkl** from your Colab download beside "
                "**app.py**, or in **used_car_regression_outputs/** beside it.")
    st.code("streamlit run app.py", language="bash")
    st.stop()

try:
    model = load_model(str(model_path), model_path.stat().st_mtime_ns)
    categories = get_categories(model)
except Exception as error:
    st.error("The saved model could not be loaded.")
    st.write("Use the complete pipeline from Colab and install the same package "
             "versions listed in requirements_model.txt.")
    with st.expander("Model loading details"):
        st.code(str(error))
    st.stop()

metadata = read_optional_json(model_path.parent / "model_metadata.json"
                              if (model_path.parent / "model_metadata.json").is_file()
                              else None)
model_name = type(model.named_steps["model"]).__name__
with st.sidebar:
    st.success("Prediction model ready")
    st.caption(f"Model: {model_name}")

predict_tab, batch_tab, performance_tab, team_tab = st.tabs(
    ["🚗 Price estimator", "📋 Multiple cars", "📊 Model performance", "🎓 Our team"]
)

with predict_tab:
    left, right = st.columns([1.3, 1], gap="large")
    with left:
        st.subheader("Tell us about the car")
        with st.form("car_form"):
            a, b = st.columns(2)
            with a:
                age = st.number_input("Vehicle age (years)", min_value=0.0,
                                      max_value=100.0, value=5.0, step=1.0)
                mileage = st.number_input("Mileage (km)", min_value=0.0,
                                          max_value=3000000.0, value=75000.0, step=1000.0)
                engine = st.number_input("Engine size (litres)", min_value=0.1,
                                         max_value=15.0, value=1.6, step=0.1)
                condition = st.slider("Condition rating", 1, 5, 4,
                                      help="Use the 1–5 condition score in the dataset.")
            with b:
                fuel_options = categories["fuel_type"]
                fuel = st.selectbox("Fuel type", fuel_options,
                                    index=fuel_options.index("Petrol") if "Petrol" in fuel_options else 0)
                transmission = st.selectbox("Transmission", categories["transmission"])
                segments = categories["market_segment"]
                segment = st.selectbox("Market segment", segments,
                                       index=segments.index("Mid_Range") if "Mid_Range" in segments else 0,
                                       format_func=lambda x: x.replace("_", " "))
                owners = st.number_input("Previous owners", min_value=0,
                                         max_value=30, value=1, step=1)
            submitted = st.form_submit_button("Estimate resale price", use_container_width=True)
        if submitted:
            car = pd.DataFrame([dict(zip(FEATURES, [age, mileage, engine, condition,
                                                   owners, fuel, transmission, segment]))])
            try:
                price = float(predict_prices(model, car, categories)[0])
                st.session_state["last_estimate"] = {
                    "car": car, "price": price,
                    "time": datetime.now(timezone.utc).isoformat(timespec="seconds"),
                }
            except (ValueError, TypeError, RuntimeError) as error:
                st.session_state.pop("last_estimate", None)
                st.error(f"Unable to predict: {error}")
    with right:
        st.subheader("Your price estimate")
        result = st.session_state.get("last_estimate")
        if result is None:
            st.markdown('<div class="price-card"><div class="muted">ESTIMATED RESALE VALUE</div>'
                        '<div class="price">RM —</div><p>Enter the car details and select '
                        'Estimate resale price.</p></div>', unsafe_allow_html=True)
        else:
            price = result["price"]
            st.markdown(f'<div class="price-card"><div class="muted">ESTIMATED RESALE VALUE</div>'
                        f'<div class="price">RM {price:,.2f}</div>'
                        f'<div class="muted">{escape(model_name)} · latest submitted car</div></div>',
                        unsafe_allow_html=True)
            if price < 0:
                st.warning("The model returned a negative price. This estimate is unreliable; "
                           "check the inputs. The model output has not been clipped.")
            st.caption("This result uses the submitted details below. Submit again after editing.")
            car = result["car"]
            st.dataframe(car.T.rename(columns={0: "Submitted value"}), use_container_width=True)
            report = car.assign(predicted_resale_price_rm=price,
                                predicted_at_utc=result["time"], model=model_name)
            st.download_button("Download estimate (CSV)", csv_bytes(report),
                               file_name="car_price_estimate.csv", mime="text/csv")
        st.caption("An educational estimate based on the supplied dataset. Prices are in RM. "
                   "This is not a guaranteed selling price or a certified valuation.")
        st.caption("The supplied dataset covers ages 0–18 years and engine sizes 1.0–3.5 L. "
                   "Estimates outside those ranges may be less reliable.")

with batch_tab:
    st.subheader("Estimate several cars at once")
    st.write("Upload a CSV or Excel file with the eight raw input columns. "
             "Blank inputs use the model's saved imputation values.")
    template = pd.DataFrame([dict(zip(FEATURES, [5, 75000, 1.6, 4, 1,
                                                categories["fuel_type"][0],
                                                categories["transmission"][0],
                                                categories["market_segment"][0]]))])
    st.download_button("Download input template", csv_bytes(template),
                       "used_car_input_template.csv", "text/csv")
    uploaded = st.file_uploader("Car records", type=["csv", "xlsx"])
    if uploaded is not None:
        try:
            if uploaded.size > 10 * 1024 * 1024:
                raise ValueError("Please use a file smaller than 10 MB.")
            content = BytesIO(uploaded.getvalue())
            frame = pd.read_csv(content) if uploaded.name.lower().endswith(".csv") else pd.read_excel(content)
            frame.columns = frame.columns.astype(str).str.strip()
            if frame.columns.duplicated().any():
                raise ValueError("Column names must be unique.")
            if len(frame) > 10000:
                raise ValueError("Please use at most 10,000 records per upload.")
            raw = validate_inputs(frame, categories)
            st.dataframe(frame.head(20), use_container_width=True)
            st.caption(f"{len(frame):,} cars · {int(raw.isna().sum().sum())} missing input cells")
            if st.button("Predict all car prices", type="primary"):
                with st.spinner("Estimating car prices…"):
                    output = frame.copy()
                    output["predicted_resale_price_rm"] = predict_prices(model, raw, categories)
                st.success(f"Completed {len(output):,} estimates.")
                if (output["predicted_resale_price_rm"] < 0).any():
                    st.warning("Some prices are negative. Review these records before use.")
                st.dataframe(output, use_container_width=True)
                st.download_button("Download all estimates (CSV)", csv_bytes(output),
                                   "used_car_batch_predictions.csv", "text/csv")
        except Exception as error:
            st.error(f"Could not process this file: {error}")

with performance_tab:
    st.subheader("Model evaluation")
    # Display recorded metrics only; never invent scores or evaluate on user inputs.
    metrics = metadata.get("selected_model_test_metrics", {})
    if all(key in metrics for key in ["MAE_RM", "RMSE_RM", "R2"]):
        c1, c2, c3 = st.columns(3)
        c1.metric("Test MAE", f"RM {metrics['MAE_RM']:,.2f}")
        c2.metric("Test RMSE", f"RM {metrics['RMSE_RM']:,.2f}")
        c3.metric("Test R²", f"{metrics['R2']:.4f}")
        st.caption("MAE and RMSE measure price errors; lower is better. "
                   "R² is a goodness-of-fit score, not an accuracy percentage.")
        st.write("**Selection method:**", metadata.get("selection_method", "See training notebook."))
        if "training_rows" in metadata and "test_rows" in metadata:
            st.caption(f"Training records: {metadata['training_rows']:,} · "
                       f"Held-out test records: {metadata['test_rows']:,}")
    else:
        st.info("Add model_metadata.json from your own Colab export beside the model "
                "to display its recorded test scores.")
    comparison_path = model_path.parent / "model_comparison_results.csv"
    if comparison_path.is_file():
        try:
            comparison = pd.read_csv(comparison_path)
            if {"Model", "RMSE_RM"}.issubset(comparison.columns):
                st.bar_chart(comparison.set_index("Model")[["RMSE_RM"]], color="#c9002b")
                st.caption("Held-out test RMSE in RM. Model selection used training cross-validation.")
            st.dataframe(comparison, use_container_width=True, hide_index=True)
        except (OSError, ValueError) as error:
            st.warning(f"Could not read the comparison results: {error}")
    with st.expander("How the prediction works"):
        st.write("The saved pipeline replaces missing numerical values with training medians, "
                 "scales numerical inputs, imputes categorical inputs and one-hot encodes them, "
                 "then predicts the resale price. These steps were fitted during training.")
        st.write("**Model:**", model_name)
        st.write("**Raw input columns:**", list(model.feature_names_in_))
        st.json(categories)

